  min-height: 100dvh !important;
  padding: calc(env(safe-area-inset-top, 0px) + 86px) clamp(18px, 4vw, 42px) calc(env(safe-area-inset-bottom, 0px) + 48px) !important;
  background: #FFFFFF !important;
  color: #0B1F33 !important;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}

html body #root#root .dp-partner-access-page .dp-partner-access-shell {
